{"module_file": {"path": "modules/leadCaptures.py", "content": "from fastapi.responses import JSONResponse
from databases import connection
import json
from observability import log_audit


def leadCaptures_sp(json_file: dict):
    conn = None
    cursor = None
    try:
        payload_list = json_file.get("leadCaptures", [{}])
        if not payload_list or not isinstance(payload_list[0], dict):
            return JSONResponse(content={"error": "Invalid payload format. 'leadCaptures' list with an object expected."}, status_code=400)

        payload = payload_list[0]
        action = payload.get("action")
        lead_capture_id = payload.get("leadCaptureId")

        old_lead_data = None
        if action in [2, 3] and lead_capture_id is not None:
            # Fetch old data for audit log if performing UPDATE or DELETE
            one_payload = {"companyId": payload.get("companyId"), "leadCaptureId": lead_capture_id}
            # Call one_leadCaptures_sp internally to get before-image
            one_result_response = one_leadCaptures_sp({"leadCaptures": [one_payload]})

            if one_result_response.status_code == 200:
                one_result_content = json.loads(one_result_response.body)
                if one_result_content.get("leadCaptures"):
                    old_lead_data = one_result_content["leadCaptures"][0]

        conn = connection()
        cursor = conn.cursor()
        cursor.execute("EXEC [dbo].[sp_leadCaptures] @pjsonfile = %s", (json.dumps(json_file),))
        # Upsert SP returns ONE row, ONE column -- use fetchone()[0]
        row = cursor.fetchone()
        json_result = row[0] if row and row[0] else '{"message": "ok"}'

        # Check for embedded error from SP as per mandatory_constraints.backend
        parsed_result = json.loads(json_result)
        if isinstance(parsed_result, dict) and parsed_result.get("error"):
            return JSONResponse(content=parsed_result, status_code=400)

        # Audit logging for UPDATE/DELETE
        if action == 2 and old_lead_data: # UPDATE
            fields_to_audit = ["fullName", "email", "companyName", "phone", "jobTitle", "message", "leadSource", "interestArea", "status", "assignedTo", "privacyConsentAccepted"]
            for field in fields_to_audit:
                old_value = old_lead_data.get(field)
                new_value = payload.get(field) # Using requested new value from payload for audit
                if old_value != new_value:
                    log_audit(
                        entity="leadCapture",
                        entity_id=str(lead_capture_id),
                        field=field,
                        old_value=str(old_value) if old_value is not None else "",
                        new_value=str(new_value) if new_value is not None else "",
                        action="UPDATE"
                    )
        elif action == 3 and old_lead_data: # DELETE
            log_audit(
                entity="leadCapture",
                entity_id=str(lead_capture_id),
                field="status", # Or log a more general entity deletion
                old_value=str(old_lead_data.get("status", "unknown")), # Assuming status is part of deleted info
                new_value="DELETED", 
                action="DELETE"
            )

        return JSONResponse(content=parsed_result, status_code=200)
    except Exception as e:
        return JSONResponse(content={"error": str(e)}, status_code=500)
    finally:
        try:
            if cursor: cursor.close()
        except Exception: pass
        try:
            if conn: conn.close()
        except Exception: pass


def all_leadCaptures_sp(json_file: dict):
    conn = None
    cursor = None
    try:
        conn = connection()
        cursor = conn.cursor()
        # Constraint: all_{plural}_sp must pass json_file to sp_all
        cursor.execute("EXEC [dbo].[sp_leadCaptures_all] @pjsonfile = %s", (json.dumps(json_file),))
        rows = cursor.fetchall()
        # SQL Server may split large FOR JSON output across multiple rows -- always join.
        # Guard against None cells and empty tables (empty table is NOT an error).
        json_result = "".join(row[0] for row in rows if row and row[0])
        if not json_result:
            return JSONResponse(content={"leadCaptures": []}, status_code=200)
        result = json.loads(json_result)
        return JSONResponse(content=result, status_code=200)
    except Exception as e:
        return JSONResponse(content={"error": str(e)}, status_code=500)
    finally:
        try:
            if cursor: cursor.close()
        except Exception: pass
        try:
            if conn: conn.close()
        except Exception: pass


def one_leadCaptures_sp(json_file: dict):
